'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=location.hash.slice(1)||sessionStorage.getItem('hexwise-token');
if(token)sessionStorage.setItem('hexwise-token',token);
history.replaceState(null,'',location.pathname);
const state={boot:null,folder:'',files:[],project:null,bytes:new Uint8Array(),saved:new Uint8Array(),original:new Uint8Array(),
 offset:0,page:0,bpr:16,mode:'hex',dirty:false,undo:[],redo:[],chain:[],busy:false,template:'grid',preferences:{},ready:false,contextBytes:16384};
const hex=bytes=>Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
const fromHex=text=>new Uint8Array((text.match(/../g)||[]).map(b=>parseInt(b,16)));
const fmt=n=>n<1024?n+' B':n<1048576?(n/1024).toFixed(1)+' KB':(n/1048576).toFixed(1)+' MB';
const address=n=>n.toString(16).toUpperCase().padStart(8,'0');
let toastTimer;
function toast(text,error=false){$('toast').textContent=text;$('toast').classList.toggle('error',error);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,error?8000:4200);}
async function api(route,data={}){const controller=new AbortController();const timer=['open','browse'].includes(route)?setTimeout(()=>controller.abort(),30000):null;try{const response=await fetch('/api/'+route,{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','X-Hexwise-Token':token||''},body:JSON.stringify(data)});const body=await response.json();if(!response.ok)throw Error(body.error||'Operation failed');return body;}catch(error){if(error.name==='AbortError')throw Error('File access timed out. Check macOS file permissions or cloud-file availability, then choose the file again. Other sessions remain available.');throw error;}finally{clearTimeout(timer);}}

function safe(fn){return async(...args)=>{try{return await fn(...args);}catch(error){toast(error.message,true);}};}
function on(id,event,fn){$(id).addEventListener(event,safe(fn));}
let persistence=Promise.resolve();
function persist(route,payload){persistence=persistence.catch(()=>{}).then(()=>api(route,payload));persistence.catch(error=>toast('Settings could not be saved: '+error.message,true));return persistence;}
function savePreferences(value){Object.assign(state.preferences,value);if(state.ready)return persist('preferences',value);}
function sessionSettings(){return {provider:$('providerSelect').value,model:$('modelInput').value.trim(),profile:$('profileSelect').value,chain:[...state.chain],layout:state.layout||null};}
function saveSession(){if(state.ready&&state.project)return persist('session',{project:state.project.id,session:sessionSettings()});}
function rememberModel(){const provider=$('providerSelect').value;savePreferences({provider,models:{...(state.preferences.models||{}),[provider]:$('modelInput').value.trim()}});saveSession();}
function applySession(project){const saved=project.session;if(saved){$('providerSelect').value=saved.provider;$('modelInput').value=saved.model;state.chain=(saved.chain||[]).filter(id=>state.boot.extensions.some(e=>e.id===id));state.layout=state.chain.includes('layout')?saved.layout:null;}else{state.chain=[];state.layout=null;}$('profileSelect').value=project.profile||'';if(state.layout){$('panelLayout').value=state.layout.template;$('panelRows').value=state.layout.rows;$('panelColumns').value=state.layout.columns;renderPanelLayout();}renderChain();}
function requireProject(){if(!state.project)throw Error('Open a file or create an application first.');}
function originalDiff(){let changes=0;for(let i=0;i<Math.max(state.bytes.length,state.original.length);i++)if(state.bytes[i]!==state.original[i])changes++;return changes;}
function markDirty(){state.dirty=hex(state.bytes)!==hex(state.saved);$('dirtyIndicator').textContent=state.dirty?'●':'';if(state.mode==='diff'&&state.project)renderDiff();updateStatus();}
function updateStatus(){const count=originalDiff();$('changeCount').textContent=count;$('snapshotCount').textContent=state.project?.snapshots.length||0;
 $('candidateStatus').textContent=state.project?(count?fmt(count)+' changed':'Protected working copy'):'No candidate yet';
 $('candidateDescription').textContent=state.project?(state.dirty?'Save your manual edits as a candidate before review.':count?'Review the diff and validation results before replacing the original. A backup will be retained.':'Your original has a protected snapshot. Edit bytes or describe your next feature.'):'Open a file to begin a protected session.';
 $('acceptButton').disabled=!state.project||state.dirty||!count||state.busy||(state.project.snapshots.find(s=>s.id===state.project.current)?.sha256===state.project.base_sha256);
 $('contextInfo').textContent=state.project?fmt(Math.min(state.contextBytes,Math.max(0,state.bytes.length-state.page)))+' file context':'No file attached';
 $('selectionInfo').textContent=state.project?'Offset 0x'+address(state.offset)+' · '+(state.bytes[state.offset]===undefined?'EOF':'0x'+state.bytes[state.offset].toString(16).padStart(2,'0')):'No selection';
 $('pageInfo').textContent=state.project?address(state.page)+' / '+fmt(state.bytes.length):'0 bytes';
 $('targetStatus').textContent=$('profileSelect').selectedOptions[0]?.textContent||'No target selected';
 $('conversationContext').textContent=state.busy?'Working on your candidate…':state.project?'Project context · '+state.project.name:'Ready when you are';
 $('statusText').textContent=state.busy?'AI request in progress · original protected':state.project?(state.dirty?'Manual edits not yet snapshotted':'Project snapshots are up to date'):'Local-first workspace';
}
async function browse(path){const data=await api('browse',{path});state.folder=data.path;state.files=data.entries;$('folderTitle').textContent=data.path.split('/').filter(Boolean).pop()||'/';$('folderTitle').title=data.path;$('parentFolder').dataset.path=data.parent;renderFiles();savePreferences({folder:data.path});}
function renderFiles(){const query=$('fileFilter').value.toLowerCase();const files=state.files.filter(f=>f.name.toLowerCase().includes(query));$('fileTree').innerHTML=files.map(f=>`<button class="file-row ${state.project?.original===f.path?'selected':''}" data-path="${esc(f.path)}" data-directory="${f.directory}" title="${esc(f.path)}"><span>${f.directory?'▱':/\.(html|js|py|css)$/.test(f.name)?'‹›':'01'}</span><span class="file-row-name">${esc(f.name)}</span>${f.directory?'':`<small>${fmt(f.size)}</small>`}</button>`).join('')||'<div class="file-empty">No matching files</div>';}
async function canLeave(){if(state.busy||state.sending){toast('Wait for the active AI request to finish.',true);return false;}if(!state.dirty){await persistence.catch(()=>{});return true;}return await confirmAction('Leave unsaved edits?','Manual changes in the editor have not been snapshotted. Save a candidate first if you want to retain them.','Discard buffer');}
async function openFile(path){if(!(await canLeave()))return;const requestId=state.openRequest=(state.openRequest||0)+1;const p=await api('open',{path});if(requestId!==state.openRequest)return;await browse(p.original.substring(0,p.original.lastIndexOf('/'))||'/');await loadProject(p);toast(p.profile&&p.profile!=='web-document'?'Project protected. Target suggested from header; confirm the platform and ABI.':'Project created. Your original has a protected snapshot.');}
async function loadProject(project){const switching=state.project?.id!==project.id;state.project=project;state.boot.recent=[project,...state.boot.recent.filter(p=>p.id!==project.id)].slice(0,50);const current=await api('bytes',{project:project.id});const original=await api('bytes',{project:project.id,snapshot:project.snapshots[0].id});state.bytes=fromHex(current.hex);state.saved=state.bytes.slice();state.original=fromHex(original.hex);state.dirty=false;state.undo=[];state.redo=[];state.page=0;state.offset=0;
 $('fileTab').textContent=project.name;$('fileName').textContent=project.name;$('fileName').title=project.original;$('projectTitle').textContent=project.name+' / protected session';$('fileSize').textContent=fmt(current.size);$('fileIdentity').textContent='SHA-256 '+current.sha256.slice(0,12)+'…';$('dirtyIndicator').textContent='';
 if(switching){state.mode='hex';applySession(project);savePreferences({activeProject:project.id});}
 renderFiles();renderHex();renderMessages();renderSnapshots();setMode(state.mode);updateStatus();}
function renderHex(){document.body.style.setProperty('--bpr',state.bpr);$('columnNumbers').innerHTML=Array.from({length:state.bpr},(_,i)=>'<span>'+i.toString(16).toUpperCase().padStart(2,'0')+'</span>').join('');
 $('emptyState').hidden=!!state.project;$('hexRows').innerHTML='';if(!state.project)return;
 const end=Math.min(state.page+state.bpr*64,state.bytes.length);let rows='';
 for(let i=state.page;i<end;i+=state.bpr){let cells='',ascii='';for(let j=i;j<Math.min(i+state.bpr,end);j++){const changed=state.bytes[j]!==state.original[j];cells+=`<input class="byte ${changed?'changed':''} ${j===state.offset?'selected':''}" data-offset="${j}" maxlength="2" value="${state.bytes[j].toString(16).padStart(2,'0')}" aria-label="Byte at offset ${address(j)}" spellcheck="false" autocomplete="off">`;ascii+=state.bytes[j]>=32&&state.bytes[j]<127?String.fromCharCode(state.bytes[j]):'·';}for(let j=end;j<i+state.bpr;j++)cells+='<span></span>';rows+=`<div class="hex-row"><span class="hex-offset" data-offset="${i}">${address(i)}</span><span class="hex-bytes">${cells}</span><span class="hex-ascii">${esc(ascii)}</span></div>`;}
 $('hexRows').innerHTML=rows;if(state.bytes.length===0)$('hexRows').innerHTML='<div class="preview-note">Empty file · use AI generation, paste bytes, or start from a GUI template.</div>';renderInspector();updateStatus();}
function selectByte(offset,focus=false){state.offset=Math.max(0,Math.min(state.bytes.length-1,offset));document.querySelectorAll('.byte.selected').forEach(e=>e.classList.remove('selected'));const el=document.querySelector(`.byte[data-offset="${state.offset}"]`);if(el){el.classList.add('selected');if(focus){el.focus();el.select();}}renderInspector();updateStatus();}
function editByte(offset,value){const before=state.bytes[offset];if(before===value)return;state.undo.push({offset,before,after:value});if(state.undo.length>1000)state.undo.shift();state.redo=[];state.bytes[offset]=value;markDirty();}
function renderInspector(){if(!state.project)return;const b=state.bytes.slice(state.offset,state.offset+8),view=new DataView(b.buffer);const value=n=>b.length>=n;let text=`<span>UINT8 <b>${b[0]??'—'}</b></span><span>UINT16 LE <b>${value(2)?view.getUint16(0,true):'—'}</b></span><span>UINT32 LE <b>${value(4)?view.getUint32(0,true):'—'}</b></span>`;if(value(4))text+=`<span>FLOAT32 <b>${view.getFloat32(0,true).toPrecision(4)}</b></span>`;$('byteInspector').innerHTML=text;}
function renderDiff(){requireProject();let rows='',total=0;for(let i=0;i<Math.max(state.bytes.length,state.original.length);i++)if(state.bytes[i]!==state.original[i]){total++;if(total<=1000)rows+=`<tr><td>${address(i)}</td><td class="old-byte">${state.original[i]===undefined?'—':state.original[i].toString(16).padStart(2,'0')}</td><td class="new-byte">${state.bytes[i]===undefined?'—':state.bytes[i].toString(16).padStart(2,'0')}</td></tr>`;}$('diffPane').innerHTML=`<p>${total} changed bytes against the first protected snapshot${total>1000?' · first 1,000 shown':''}.</p><table><thead><tr><th>OFFSET</th><th>ORIGINAL</th><th>CANDIDATE</th></tr></thead><tbody>${rows||'<tr><td colspan="3">No byte changes.</td></tr>'}</tbody></table>`;}
async function setMode(mode){state.mode=mode;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('hexPane').hidden=mode!=='hex';$('diffPane').hidden=mode!=='diff';$('previewPane').hidden=mode!=='preview';if(!state.project)return;if(mode==='diff')renderDiff();if(mode==='preview'){if(state.dirty){$('previewPane').innerHTML='<p class="preview-note">Save a candidate to preview the current buffer.</p>';return;}if(/\.(html|htm|svg)$/i.test(state.project.name)){$('previewPane').innerHTML='<iframe title="Isolated candidate preview" sandbox="allow-scripts"></iframe>';const preview=await api('preview',{project:state.project.id});$('previewPane').querySelector('iframe').src=preview.url;}else{let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(state.bytes);}catch{text=null;}$('previewPane').innerHTML=text!==null?'<pre class="code-view">'+esc(text)+'</pre>':'<p class="preview-note">Native execution needs a matching isolated target runner. Export the candidate for testing; bytes are not executed on the host.</p>';}}}
async function stage(label='Manual edit'){requireProject();if(state.busy)throw Error('Wait for the active AI operation.');await saveSession();if(!state.dirty)return state.project;const p=await api('stage',{project:state.project.id,snapshot:state.project.current,hex:hex(state.bytes),label});const page=state.page,offset=state.offset;await loadProject(p);state.page=page;state.offset=offset;renderHex();toast('Candidate saved. Original unchanged.');return p;}
function assistantText(raw){try{const p=JSON.parse(raw.replace(/^```(?:json)?\s*|\s*```$/g,''));if(p.status==='needs_input'||p.status==='unsupported'){const reason=p.message||p.reason||'More details are needed before continuing.';const missing=Array.isArray(p.missing)?p.missing.filter(x=>typeof x==='string'):[];return reason+(missing.length?'\n\nDetails to provide: '+missing.map(x=>x.replace(/_/g,' ')).join(', '):'')+(p.status==='needs_input'?'\n\nReply below with the details. You can also save target settings under Project → Target & verification contract.':'');}return p.message||raw;}catch{return raw;}}
function renderMessages(){if(!state.project?.messages.length){$('chatMessages').innerHTML='<div class="welcome-message"><div class="assistant-avatar">H·</div><span class="eyebrow">PROTECTED SESSION CREATED</span><h2>Let’s work on<br>'+esc(state.project.name)+'.</h2><p>Your file has a protected snapshot. Choose its target profile and a model, then describe the change you have in mind.</p><div class="workflow-mini"><span>01 <b>Inspect</b></span><span>02 <b>Modify</b></span><span>03 <b>Review</b></span></div><p class="muted">AI proposals become candidates. You decide what ships.</p></div>';return;}
 $('chatMessages').innerHTML=state.project.messages.map(m=>{let text=m.text,proposal=false;if(m.role==='assistant'){try{const parsed=JSON.parse(text.replace(/^```(?:json)?\s*|\s*```$/g,''));text=assistantText(text);proposal=!!(parsed.edits||parsed.artifact);}catch{}}return `<article class="message ${esc(m.role)}"><div class="message-head"><span class="avatar">${m.role==='user'?'You':m.role==='system'?'!':'H·'}</span>${m.role==='user'?'You':m.role==='system'?'Hexwise check':'Hexwise'}<small>${esc(m.step||m.provider||'')}</small></div><div class="message-content">${esc(text)}</div>${m.role==='assistant'&&(proposal||m.outcome)?'<span class="proposal-pill '+esc(m.outcome||'')+'">'+esc(({applied:'◇ Checked proposal saved as a candidate',rejected:'! Proposal rejected · bytes unchanged',cancelled:'◇ Cancelled · no changes applied',analysis:'◇ Analysis only',needs_input:'◇ Waiting for your details · bytes unchanged',unsupported:'◇ Unsupported request · bytes unchanged'})[m.outcome]||'◇ Byte proposal received · inspect snapshots')+'</span>':''}</article>`;}).join('');$('chatMessages').scrollTop=$('chatMessages').scrollHeight;}
function renderSnapshots(){if(!state.project){$('snapshotList').innerHTML='<p class="dialog-note">Open a file to start a versioned session.</p>';return;}$('snapshotList').innerHTML=state.project.snapshots.slice().reverse().map(s=>`<article class="snapshot-item ${s.id===state.project.current?'current':''}"><strong>${esc(s.label)}</strong><p>${new Date(s.created*1000).toLocaleTimeString()} · ${fmt(s.bytes)} · ${s.sha256.slice(0,12)}</p><button data-restore="${s.id}" ${s.id===state.project.current?'disabled':''}>Restore as candidate</button></article>`).join('');}
function renderChain(){$('chainChips').innerHTML=state.chain.map((id,i)=>{const e=state.boot.extensions.find(e=>e.id===id);return `<button data-remove-chain="${i}" title="Remove from chain">${i+1}. ${esc(e?.name||id)} ×</button>`;}).join('');renderPromptChoices();saveSession();}
async function send(){requireProject();if(state.busy||state.sending)return;const text=$('chatInput').value.trim();if(!text)return;if(!$('profileSelect').value)throw Error('Choose the architecture/platform profile first.');if(!$('modelInput').value.trim())throw Error('Discover or enter a model ID first.');state.sending=true;$('sendButton').disabled=true;try{if(state.dirty)await stage('Manual edits before AI');await saveSession();}catch(error){state.sending=false;$('sendButton').disabled=false;throw error;}state.busy=true;setBusy(true);$('hexRows').inert=true;$('chatInput').disabled=true;$('sendButton').disabled=true;$('sendButton').textContent='Working…';updateStatus();
 try{const p=await api('chat',{project:state.project.id,snapshot:state.project.current,text,provider:$('providerSelect').value,model:$('modelInput').value.trim(),profile:$('profileSelect').value,chain:state.chain,offset:state.page,context_bytes:state.contextBytes,layout:state.layout||null});await loadProject(p);$('chatInput').value='';toast(p.messages.at(-1)?.outcome==='needs_input'?'More details needed. Reply in chat to continue.':'Response retained. Review any new candidates.');}finally{state.busy=false;state.sending=false;setBusy(false);$('hexRows').inert=false;$('chatInput').disabled=false;$('sendButton').disabled=false;$('sendButton').innerHTML='Send <span>↗</span>';updateStatus();if(state.project){const p=await api('project',{project:state.project.id});await loadProject(p);}}}

function setBusy(busy){for(const id of ['promptsPanel','chainChips'])$(id).inert=busy;for(const id of ['providerSelect','profileSelect','modelInput','loadModels','contextSize'])$(id).disabled=busy;$('stopButton').hidden=!busy;$('stopButton').disabled=false;}

function modal(title,body,buttons=[],eyebrow='HEXWISE STUDIO'){if($('dialog').open)$('dialog').close();$('dialogTitle').textContent=title;$('dialogEyebrow').textContent=eyebrow;$('dialogBody').innerHTML=body;$('dialogBody').scrollTop=0;$('dialogFooter').innerHTML='';for(const b of buttons){const el=document.createElement('button');el.textContent=b.label;if(b.primary)el.className='primary';el.addEventListener('click',safe(async()=>{el.disabled=true;try{await b.action();}finally{el.disabled=false;}}));$('dialogFooter').append(el);}$('dialog').showModal();}
function field(id,label,value='',type='text',note=''){return `<div class="form-field"><label for="${id}">${esc(label)}</label><input id="${id}" type="${type}" value="${esc(value)}">${note?'<small>'+esc(note)+'</small>':''}</div>`;}
function confirmAction(title,body,label){return new Promise(resolve=>{let done=false;const closed=()=>{if(!$('dialog').open)finish(false);};const finish=value=>{if(!done){done=true;$('dialog').removeEventListener('close',closed);resolve(value);}};modal(title,'<p class="dialog-note">'+esc(body)+'</p>',[{label:'Cancel',action:()=>{$('dialog').close();finish(false);}},{label,primary:true,action:()=>{$('dialog').close();finish(true);}}]);$('dialog').addEventListener('close',closed);});}

function pathDialog(kind){const folder=kind==='folder';modal(folder?'Open workspace folder':'Open a file',field('pathInput',folder?'Directory path':'File path',state.folder||state.boot.workspace,'text','Enter an absolute path. You can browse directories in the explorer. Opening a file creates a protected project.'),[{label:'Cancel',action:()=>$('dialog').close()},{label:folder?'Open folder':'Open file',primary:true,action:async()=>{const path=$('pathInput').value;if(folder){await browse(path);$('dialog').close();}else{$('dialog').close();await openFile(path);}}}]);$('pathInput').focus();}
function newDialog(templates=false){state.template=templates?'grid':'';const cards=state.boot.templates.map(t=>`<button class="template-card ${t.id===state.template?'selected':''}" data-template="${t.id}"><div class="template-visual ${t.id}">${Array.from({length:t.id==='grid'?12:t.id==='studio'?3:2},()=>'<i></i>').join('')}</div><strong>${esc(t.name)}</strong><small>${esc(t.description)}</small></button>`).join('');modal(templates?'Start with a GUI layout':'Create a new application',`<p class="dialog-note">Start from an empty artifact or a working web GUI template. A project and initial snapshot are created automatically.</p><div class="template-grid">${cards}</div><div class="form-grid">${field('newName','Filename',templates?'application.html':'untitled.bin')}${field('newDirectory','Project directory',state.folder||state.boot.workspace)}${field('gridRows','Rows',4,'number')}${field('gridColumns','Columns',4,'number')}</div><p class="dialog-note">Grid layouts support 1–8 rows and columns. GUI starters are standalone HTML applications; native output requires a complete target contract.</p>`,[{label:'Empty artifact',action:()=>{state.template='';document.querySelectorAll('[data-template]').forEach(e=>e.classList.remove('selected'));$('newName').value='untitled.bin';}},{label:'Create application',primary:true,action:async()=>{const rows=Number($('gridRows').value),columns=Number($('gridColumns').value);const p=await api('create',{name:$('newName').value,directory:$('newDirectory').value,template:state.template,rows,columns});const template=state.boot.templates.find(t=>t.id===state.template);const layout=template?{template:state.template,rows,columns}:null;await api('session',{project:p.id,session:{...sessionSettings(),profile:p.profile,chain:[...(template?.chain||[])],layout}});p.session={...sessionSettings(),chain:[...(template?.chain||[])],layout};$('dialog').close();await browse(p.original.substring(0,p.original.lastIndexOf('/')));await loadProject(p);renderChain();toast('Application created with a protected initial snapshot.');}}]);document.querySelectorAll('[data-template]').forEach(button=>button.addEventListener('click',()=>{state.template=button.dataset.template;document.querySelectorAll('[data-template]').forEach(e=>e.classList.toggle('selected',e===button));$('newName').value='application.html';const template=state.boot.templates.find(t=>t.id===state.template);$('gridRows').value=template.rows;$('gridColumns').value=template.columns;}));}
function promptManager(){const rows=state.boot.extensions.map(e=>`<div class="extension-row"><input type="checkbox" data-chain-id="${esc(e.id)}" ${state.chain.includes(e.id)?'checked':''} aria-label="Add ${esc(e.name)} to chain"><div><strong>${esc(e.name)}</strong><small>${esc(e.category||'Custom')}</small></div><button data-edit-extension="${esc(e.id)}">Edit prompt</button></div>`).join('');modal('Prompt extension library',`<p class="dialog-note">Select up to eight extensions in execution order. Reorder them in the Prompts tab. Changes are saved with the current project.</p>${rows}`,[{label:'New extension',action:()=>editExtension()},{label:'Done',primary:true,action:()=>{$('dialog').close();showPanel('prompts');}}]);document.querySelectorAll('[data-edit-extension]').forEach(b=>b.addEventListener('click',()=>editExtension(b.dataset.editExtension)));document.querySelectorAll('[data-chain-id]').forEach(b=>b.addEventListener('change',safe(()=>{const id=b.dataset.chainId;if(b.checked&&state.chain.length>=8){b.checked=false;throw Error('A chain may contain at most eight prompts.');}state.chain=state.chain.filter(x=>x!==id);if(b.checked)state.chain.push(id);else if(id==='layout')state.layout=null;renderChain();})));}
function editExtension(id){const extension=state.boot.extensions.find(e=>e.id===id)||{id:'custom-'+Date.now(),name:'New feature',category:'Custom',prompt:''};modal('Edit prompt extension',`${field('extensionName','Feature name',extension.name)}${field('extensionCategory','Category',extension.category)}<div class="form-field"><label for="extensionPrompt">Prompt instructions</label><textarea id="extensionPrompt">${esc(extension.prompt)}</textarea><small>Feature instructions are chained after the selected target profile. They cannot grant file or execution permissions.</small></div>`,[{label:'Back to library',action:()=>promptManager()},...(id&&!state.boot.default_extensions.some(e=>e.id===id)?[{label:'Delete extension',action:async()=>{if(!await confirmAction('Delete this custom prompt?','The prompt will be removed from the library and active chain. Existing project conversation and snapshots are retained.','Delete prompt'))return;const result=await api('extensions',{extensions:state.boot.extensions.filter(e=>e.id!==id)});state.boot.extensions=result.extensions;state.chain=state.chain.filter(e=>e!==id);renderChain();$('extensionCount').textContent=result.extensions.length;promptManager();}}]:[]),...(id&&state.boot.default_extensions.some(e=>e.id===id)?[{label:'Restore built-in text',action:()=>{const original=state.boot.default_extensions.find(e=>e.id===id);$('extensionName').value=original.name;$('extensionCategory').value=original.category;$('extensionPrompt').value=original.prompt;}}]:[]),{label:'Save extension',primary:true,action:async()=>{const e={...extension,name:$('extensionName').value,category:$('extensionCategory').value,prompt:$('extensionPrompt').value};const library=state.boot.extensions.filter(x=>x.id!==extension.id);library.push(e);const data=await api('extensions',{extensions:library});state.boot.extensions=data.extensions;renderChain();$('extensionCount').textContent=library.length;promptManager();toast('Prompt extension saved locally.');}}]);}
function settings(){const current=$('providerSelect').value;const options=state.boot.providers.map(p=>`<option value="${p.id}" ${p.id===current?'selected':''}>${esc(p.label)}${p.configured?' · configured':''}</option>`).join('');modal('Model connections',`<p class="dialog-note">Provider adapters run locally. Existing environment credentials are reused; keys entered here remain in server memory for this app session. Project files never store API keys.</p><div class="form-field"><label for="settingsProvider">Provider</label><select id="settingsProvider">${options}</select></div>${field('settingsBase','API endpoint',state.boot.providers.find(p=>p.id===current)?.base||'')}${field('settingsKey','Session API key','','password','Leave blank to keep the existing environment or session credential.')}${field('githubKey','GitHub token (optional)','','password','Needed for private repositories and creating draft pull requests. Local Git uses your installed Git authentication.')}`, [{label:'Cancel',action:()=>$('dialog').close()},{label:'Save connection',primary:true,action:async()=>{state.boot.providers=await api('configure',{provider:$('settingsProvider').value,base:$('settingsBase').value,key:$('settingsKey').value,github_key:$('githubKey').value});$('providerSelect').value=$('settingsProvider').value;savePreferences({provider:$('providerSelect').value});$('dialog').close();renderProviders();saveSession();toast('Connection configured for this session.');}}]);$('settingsProvider').addEventListener('change',()=>{$('settingsBase').value=state.boot.providers.find(p=>p.id===$('settingsProvider').value).base;$('settingsKey').value='';});}
function renderProviders(){const current=$('providerSelect').value||state.preferences.provider||'openai';$('providerSelect').innerHTML=state.boot.providers.map(p=>`<option value="${p.id}">${esc(p.label)}</option>`).join('');$('providerSelect').value=current;$('providerStatus').textContent=state.boot.providers.filter(p=>p.configured).length+' provider slots ready';$('modelInput').value=state.preferences.models?.[current]||'';}
async function models(){const provider=$('providerSelect').value;$('loadModels').disabled=true;try{const data=await api('models',{provider});$('modelOptions').innerHTML=data.models.map(m=>'<option value="'+esc(m)+'">').join('');if(!$('modelInput').value&&data.models.length){const preferred=data.models.find(m=>/^gpt-.*(mini|sol)/.test(m))||data.models.find(m=>/^claude/.test(m))||data.models[0];$('modelInput').value=preferred;rememberModel();}toast(data.models.length+' models available. Choose or enter a model ID.');}finally{$('loadModels').disabled=false;}}
async function profileDialog(){const identity=$('profileSelect').value;if(!identity)throw Error('Choose a target profile first.');const data=await api('profile',{profile:identity});modal('Architecture system prompt','<p class="dialog-note">This target prompt is baked into the application and composed with the desktop response adapter and selected extensions.</p><pre class="code-view">'+esc(data.text)+'</pre>',[{label:'Close',action:()=>$('dialog').close()}]);}
async function accept(){requireProject();if(state.busy)throw Error('Wait for the active AI operation.');if(state.dirty)throw Error('Save the current buffer as a candidate first.');if(!await confirmAction('Replace the original file?','The current candidate will replace '+state.project.original+'. Hexwise checks the original hash and retains an exact backup before replacement. This does not establish executable validity or behavioral correctness.','Accept & replace'))return;const p=await api('accept',{project:state.project.id,snapshot:state.project.current});await loadProject(p);toast('Original replaced. Backup retained at '+p.accepted.backup);}
async function validate(){requireProject();if(state.dirty)await stage();const result=await api('validate',{project:state.project.id,profile:$('profileSelect').value});modal('Candidate check results','<p class="dialog-note">These are local format checks. Behavioral tests and native execution require a matching target runner.</p><pre class="code-view">'+esc(JSON.stringify(result,null,2))+'</pre>',[{label:'Close',action:()=>$('dialog').close()}]);}
async function exportCandidate(){requireProject();if(state.dirty)await stage();modal('Export candidate',field('exportPath','New output path',state.folder+'/'+state.project.name+'.candidate','text','Exports never overwrite an existing file.'),[{label:'Export',primary:true,action:async()=>{const result=await api('export',{project:state.project.id,path:$('exportPath').value});$('dialog').close();toast('Candidate exported to '+result.path);}}]);}
function github(){const f=state.gitForm||{path:state.folder,repository:'woodyk/concepts-and-proofs',message:'',branch:'',title:'',head:'',base:'main',body:'Created with Hexwise.'};const capture=()=>{state.gitForm=Object.fromEntries(['path','repository','message','branch','title','head','base','body'].map(k=>[k,$('git-'+k).value]));return state.gitForm;};modal('Git & GitHub',`<p class="dialog-note">Local Git uses your installed authentication. GitHub API writes require a session token. Inspect status before staging, committing or publishing.</p>${field('git-path','Local repository directory',f.path)}<div class="git-actions">${[['status','Status'],['diff','Diff summary'],['log','History'],['fetch','Fetch'],['stage','Stage all'],['push','Push'],['init','Initialize']].map(([id,label])=>`<button data-git="${id}">${label}</button>`).join('')}</div><div class="form-grid">${field('git-message','Commit message',f.message)}${field('git-branch','New branch name',f.branch)}</div><div class="git-actions"><button data-git="commit">Commit staged changes</button><button data-git="branch">Create branch</button></div>${field('git-repository','GitHub repository',f.repository,'text','owner/repository')}<div class="git-actions"><button id="githubInfo">Repository info</button><button id="githubPulls">Pull requests</button><button id="openRemote">Open on GitHub ↗</button></div><details><summary>Create a draft pull request</summary>${field('git-title','Pull request title',f.title)}<div class="form-grid">${field('git-head','Head branch',f.head)}${field('git-base','Base branch',f.base)}</div>${field('git-body','Description',f.body)}<button id="githubCreatePR">Create draft pull request</button></details><pre id="gitOutput" class="code-view">${esc(state.gitOutput||'Choose an action to inspect a repository.')}</pre>`,[{label:'Connections',action:()=>{capture();settings();}},{label:'Close',action:()=>{capture();$('dialog').close();}}]);document.querySelectorAll('[data-git]').forEach(b=>b.addEventListener('click',safe(async()=>{const action=b.dataset.git,f=capture();if(action==='commit'&&!f.message.trim())throw Error('Enter a commit message.');if(action==='branch'&&!f.branch.trim())throw Error('Enter a new branch name.');if(['stage','push','init'].includes(action)){const accepted=await confirmAction('Run Git '+action+'?','Repository directory: '+f.path+'. '+(action==='stage'?'All nonignored changes will be staged.':action==='push'?'Commits will be published to the configured remote.':'Initialize Git in this directory.'),'Run '+action);if(!accepted){github();return;}}const result=await api('git',{action,path:f.path,message:f.message,name:f.branch});state.gitOutput=(result.ok?'':'Git did not complete successfully.\n')+(result.output||'Done.');github();})));for(const [id,action] of [['githubInfo','info'],['githubPulls','pulls']])$(id).addEventListener('click',safe(async()=>{const f=capture();state.gitOutput=JSON.stringify(await api('github',{action,repository:f.repository}),null,2);$('gitOutput').textContent=state.gitOutput;}));$('openRemote').onclick=()=>{const f=capture();if(/^[\w.-]+\/[\w.-]+$/.test(f.repository))window.open('https://github.com/'+f.repository,'_blank','noopener');};$('githubCreatePR').onclick=safe(async()=>{const f=capture();if(!f.title.trim()||!f.head.trim()||!f.base.trim())throw Error('Enter a title, head branch and base branch.');if(!await confirmAction('Create this draft pull request?',f.repository+': '+f.head+' → '+f.base+' · '+f.title,'Create draft')){github();return;}const result=await api('github',{action:'create_pr',repository:f.repository,title:f.title,head:f.head,base:f.base,body:f.body});state.gitOutput='Draft pull request created: '+result.html_url;github();});}

function help(){modal('A workspace for every change','<p class="dialog-note">Hexwise combines a byte editor, architecture-aware AI and a protected project history.</p><div class="code-view">1. Open a folder, then select a file. Its original is snapshotted automatically.\n2. Inspect and edit bytes, or choose a target profile and AI provider.\n3. Add feature extensions to run an ordered prompt chain.\n4. Save manual edits as a candidate. Compare changes and check the file.\n5. Preview web applications in a restricted frame; export native candidates to an isolated test runner.\n6. Accept & replace only when satisfied. The original is backed up first.\n\n⌘O Open file · ⌘N New application · ⌘S Save candidate\n⌘F Find · ⌘Z Undo byte edit · ⌘K Command palette\n⌘Enter Send · arrow keys Navigate bytes\n\nCloud requests include the selected 4, 16 or 64 KiB of bytes from the current page and recent project conversation. Choose Ollama to use a local endpoint.\n\nThis is an initial developer release. Native loader, ABI and behavioral validation are not supplied by a successful hex patch.</div>',[{label:'Close',action:()=>$('dialog').close()}]);}
function runDialog(){requireProject();modal('Test in an isolated Linux container',`<p class="dialog-note">Runs the saved candidate in Docker with networking disabled, a read-only filesystem, no added capabilities, 128 MiB of memory and a 15-second timeout. Linux x86-64 and ARM64 executables only. Docker and a matching runtime image must already be available; Hexwise does not pull images or execute the file on your host.</p>${field('runImage','Existing runtime image','debian:bookworm-slim','text','Prefer a pinned image digest and dependencies matching your target.')}<div class="form-field"><label for="runArguments">Arguments as JSON</label><input id="runArguments" value="[]"></div><div class="form-field"><label for="runExpected">Expected stdout (optional)</label><textarea id="runExpected"></textarea></div><pre id="runResult" class="code-view">No execution has been started.</pre>`,[{label:'Run candidate',primary:true,action:async()=>{if(state.dirty)throw Error('Save the candidate before testing.');const expected=$('runExpected').value;const result=await api('run',{project:state.project.id,snapshot:state.project.current,profile:$('profileSelect').value,image:$('runImage').value,arguments:JSON.parse($('runArguments').value),expected_stdout:expected||null});$('runResult').textContent=JSON.stringify(result,null,2);}}]);}
function contractField(field,value){const id='contract_'+field.key;const common=`id="${esc(id)}"`;let control;if(field.control==='textarea'){control=`<textarea ${common}>${esc(value)}</textarea>`;}else if(field.control==='select'){const choices=[...field.choices];if(value&&!choices.includes(value))choices.unshift(value);control=`<select ${common}><option value="">Decide in chat / not specified</option>${choices.map(choice=>`<option value="${esc(choice)}" ${choice===value?'selected':''}>${esc(choice)}</option>`).join('')}</select>`;}else{control=`<input ${common} list="${esc(id)}_choices" value="${esc(value)}" placeholder="Choose a suggestion or enter your own"><datalist id="${esc(id)}_choices">${field.choices.map(choice=>`<option value="${esc(choice)}"></option>`).join('')}</datalist>`;}return `<div class="form-field ${field.control==='textarea'?'full':''}"><label for="${esc(id)}">${esc(field.label)}</label>${control}<small>${esc(field.help)}</small></div>`;}
async function targetContract(){requireProject();const project=state.project;const profile=$('profileSelect').value;if(!profile)throw Error('Choose a target profile first.');const options=await api('contract-options',{profile});if(state.project?.id!==project.id)throw Error('The active project changed. Open the contract again.');const c=project.contract||{};const mismatch=c.profile_id&&c.profile_id!==profile;const body=options.fields.map(field=>contractField(field,c[field.key]??(mismatch?'':field.default||''))).join('');modal('Target & verification contract',`<p class="dialog-note"><strong>${esc(options.label)}</strong> · Save a draft now, or provide these details through chat. Native byte proposals require concrete behavior, target and validation details. Blank fields remain unknown; no tests or signing are configured by this form.</p>${mismatch?'<p class="dialog-note">This draft was saved for another profile. Review every value for the selected target before saving.</p>':''}<div class="form-grid contract-form">${body}</div>`,[{label:'Save draft contract',primary:true,action:async()=>{if(state.project?.id!==project.id||$('profileSelect').value!==profile)throw Error('Project or target changed. Reopen the contract.');const contract={...c};for(const field of options.fields)contract[field.key]=$('contract_'+field.key).value.trim();const p=await api('contract',{project:project.id,profile,contract});state.project=p;$('dialog').close();toast('Draft contract saved. Unknown details can be clarified in chat.');}}]);}

const actions={run:runDialog,contract:targetContract,openFile:()=>{if(window.webkit?.messageHandlers?.openFile)window.webkit.messageHandlers.openFile.postMessage(null);else pathDialog('file');},openFolder:()=>{if(window.webkit?.messageHandlers?.openFolder)window.webkit.messageHandlers.openFolder.postMessage(null);else pathDialog('folder');},new:async()=>{if(await canLeave())newDialog(false);},templates:async()=>{if(await canLeave())newDialog(true);},prompts:()=>promptManager(false),settings,profile:profileDialog,github,help,stage,accept,validate,export:exportCandidate,
 undo:()=>{const edit=state.undo.pop();if(edit){state.bytes[edit.offset]=edit.before;state.redo.push(edit);renderHex();markDirty();}},redo:()=>{const edit=state.redo.pop();if(edit){state.bytes[edit.offset]=edit.after;state.undo.push(edit);renderHex();markDirty();}},
 find:()=>{$('findBar').hidden=false;$('findInput').focus();},inspect:()=>{$('byteInspector').hidden=!$('byteInspector').hidden;renderInspector();},
 snapshots:()=>showPanel('history'),preview:()=>setMode('preview'),diff:()=>setMode('diff'),
 copy:async()=>{requireProject();await navigator.clipboard.writeText(state.bytes[state.offset]?.toString(16).padStart(2,'0')||'');toast('Selected byte copied.');},
 paste:()=>{requireProject();modal('Replace buffer from hex','<div class="form-field"><label for="pasteHex">Complete hex byte stream</label><textarea id="pasteHex" placeholder="00ff…"></textarea><small>This changes only the editor buffer. Save a candidate to retain it.</small></div>',[{label:'Replace buffer',primary:true,action:()=>{const text=$('pasteHex').value.replace(/\s/g,'');if(!/^(?:[a-fA-F0-9]{2})*$/.test(text))throw Error('Enter complete hex byte pairs.');state.bytes=fromHex(text);state.undo=[];state.redo=[];state.page=0;renderHex();markDirty();$('dialog').close();}}]);},
 recent:()=>modal('Recent sessions',state.boot.recent.map(p=>`<button class="command-item" data-recent="${p.id}">${esc(p.name)}<small> — ${esc(p.original)}</small></button>`).join('')||'<p class="dialog-note">No recent sessions yet.</p>'),
 resetLayout:()=>{for(const key of ['--left','--right','--composer']){document.body.style.removeProperty(key);}savePreferences({paneSizes:{}});toast('Pane sizes reset.');},
 projectInfo:()=>{requireProject();modal('Project & recovery','<p class="dialog-note">All snapshots, chat history and acceptance backups for this session are retained here.</p><pre class="code-view">'+esc(JSON.stringify({original:state.project.original,project_directory:state.project.project_directory,base_sha256:state.project.base_sha256,current:state.project.current,accepted:state.project.accepted},null,2))+'</pre>');},
};
const menuDefs={File:[['Open file…','openFile','⌘O'],['Open folder…','openFolder'],['New application…','new','⌘N'],['GUI templates…','templates'],['Recent sessions…','recent'],null,['Save candidate','stage','⌘S'],['Export candidate…','export']],Edit:[['Undo byte edit','undo','⌘Z'],['Redo byte edit','redo','⇧⌘Z'],null,['Copy selected byte','copy'],['Replace buffer from hex…','paste'],['Find / go to offset','find','⌘F']],View:[['Hex editor','hex'],['Compare changes','diff'],['Preview candidate','preview'],['Byte inspector','inspect'],['Snapshot history','snapshots'],['Reset pane sizes','resetLayout']],Project:[['Target & verification contract…','contract'],['Check candidate','validate'],['Run in isolated Linux container…','run'],['Accept & replace…','accept'],['Project & recovery…','projectInfo']],AI:[['Provider connections…','settings'],['Architecture system prompt…','profile'],['Prompt extension manager…','prompts']],GitHub:[['Git & GitHub console…','github']],Help:[['Workflow & shortcuts','help']]};
function showPanel(panel){savePreferences({rightPanel:panel});$('chatMessages').hidden=panel!=='chat';$('snapshotList').hidden=panel!=='history';$('promptsPanel').hidden=panel!=='prompts';$('reviewCard').hidden=panel==='prompts';document.querySelectorAll('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===panel);b.setAttribute('aria-selected',String(b.dataset.panel===panel));});if(panel==='prompts')renderPromptChoices();}
function renderPromptChoices(){if(!state.boot)return;const query=$('panelFeatureSearch').value.trim().toLowerCase();const features=state.boot.extensions.filter(e=>e.id!=='layout'&&[e.name,e.category,e.prompt].join(' ').toLowerCase().includes(query));$('panelFeatureList').innerHTML=features.map(e=>`<div class="prompt-feature ${state.chain.includes(e.id)?'selected':''}"><label><input type="checkbox" data-prompt-feature="${esc(e.id)}" ${state.chain.includes(e.id)?'checked':''}><span><strong>${esc(e.name)}</strong><small>${esc(e.category||'Custom')}</small></span></label><details><summary>View instructions</summary><p>${esc(e.prompt)}</p><button data-panel-edit-prompt="${esc(e.id)}">Edit prompt</button></details></div>`).join('')||'<p class="prompt-hint">No matching feature prompts.</p>';$('panelChainCount').textContent=state.chain.length;$('panelChainList').innerHTML=state.chain.map((id,i)=>{const e=state.boot.extensions.find(e=>e.id===id);return `<div class="prompt-chain-row"><span class="prompt-chain-number">${i+1}</span><strong>${esc(e?.name||id)}</strong><button data-chain-move="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Move ${esc(e?.name||id)} up">↑</button><button data-chain-move="${i}" data-direction="1" ${i===state.chain.length-1?'disabled':''} aria-label="Move ${esc(e?.name||id)} down">↓</button><button data-chain-remove="${i}" aria-label="Remove ${esc(e?.name||id)}">×</button></div>`;}).join('')||'<p class="prompt-hint">No extensions selected. Add a layout or feature above.</p>';const layout=state.layout;const template=state.boot.templates.find(t=>t.id===layout?.template);$('panelLayoutStatus').textContent=layout&&state.chain.includes('layout')?`${template?.name||'Layout'} · ${layout.rows} × ${layout.columns} attached.`:'No layout attached to this request.';}
function renderPanelLayout(){const id=$('panelLayout').value;const rows=Math.min(8,Math.max(1,Number($('panelRows').value)||1));const columns=Math.min(8,Math.max(1,Number($('panelColumns').value)||1));const preview=$('panelLayoutPreview');preview.className='prompt-layout-preview '+id;preview.style.gridTemplateColumns=`repeat(${columns},1fr)`;preview.innerHTML=Array.from({length:Math.min(rows*columns,64)},()=>'<i></i>').join('');}
function initializePromptsPanel(){$('panelLayout').innerHTML=state.boot.templates.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('');renderPanelLayout();renderPromptChoices();}

function menu(name,button){document.querySelector('.dropdown-menu')?.remove();const menu=document.createElement('div');menu.className='dropdown-menu';for(const entry of menuDefs[name]){if(!entry){menu.append(document.createElement('hr'));continue;}const b=document.createElement('button');b.innerHTML='<span>'+esc(entry[0])+'</span><kbd>'+esc(entry[2]||'')+'</kbd>';b.addEventListener('click',safe(async()=>{menu.remove();await runAction(entry[1]);}));menu.append(b);}const rect=button.getBoundingClientRect();menu.style.left=rect.left+'px';menu.style.top=rect.bottom+3+'px';document.body.append(menu);}
async function runAction(name){if(state.busy&&!['help','profile','snapshots','hex','diff','find','inspect'].includes(name))throw Error('Wait for the active AI operation or stop it first.');if(name==='hex')return setMode('hex');if(actions[name])return actions[name]();}
function commandPalette(){const entries=Object.entries(menuDefs).flatMap(([group,entries])=>entries.filter(Boolean).map(e=>({group,label:e[0],action:e[1]})));modal('What would you like to do?','<div class="form-field"><input id="commandSearch" placeholder="Search commands…"></div><div id="commandResults"></div>');const render=()=>{$('commandResults').innerHTML=entries.filter(e=>e.label.toLowerCase().includes($('commandSearch').value.toLowerCase())).map(e=>`<button class="command-item" data-command="${e.action}">${esc(e.label)} <small>· ${e.group}</small></button>`).join('');};$('commandSearch').addEventListener('input',render);render();$('commandSearch').focus();}
function fitPanes(){const style=getComputedStyle(document.body);const available=Math.max(430,$('workspace').clientWidth-465);let left=Math.min(420,Math.max(160,parseFloat(style.getPropertyValue('--left'))));let right=Math.min(650,Math.max(270,parseFloat(style.getPropertyValue('--right'))));if(left+right>available){right=Math.max(270,available-left);left=Math.max(160,available-right);}const composer=Math.min(Math.max(165,window.innerHeight-450),440,Math.max(165,parseFloat(style.getPropertyValue('--composer'))));const sizes={'--left':left,'--right':right,'--composer':composer};for(const [key,value] of Object.entries(sizes))document.body.style.setProperty(key,value+'px');state.preferences.paneSizes=sizes;}
function splitters(){for(const [id,key,minimum,maximum,direction] of [['leftSplitter','--left',160,420,1],['rightSplitter','--right',270,650,-1],['composerSplitter','--composer',165,440,-1]]){const splitter=$(id);const change=delta=>{const current=parseFloat(getComputedStyle(document.body).getPropertyValue(key));const value=Math.min(maximum,Math.max(minimum,current+delta));document.body.style.setProperty(key,value+'px');state.preferences.paneSizes={...(state.preferences.paneSizes||{}),[key]:value};fitPanes();};const saved=state.preferences.paneSizes?.[key];if(saved)document.body.style.setProperty(key,saved+'px');splitter.addEventListener('pointerdown',event=>{event.preventDefault();splitter.setPointerCapture(event.pointerId);let previous=key==='--composer'?event.clientY:event.clientX;const move=e=>{const current=key==='--composer'?e.clientY:e.clientX;change((current-previous)*direction);previous=current;};const end=()=>{splitter.removeEventListener('pointermove',move);splitter.removeEventListener('pointerup',end);savePreferences({paneSizes:state.preferences.paneSizes||{}});};splitter.addEventListener('pointermove',move);splitter.addEventListener('pointerup',end);});splitter.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();change((e.key==='ArrowLeft'||e.key==='ArrowUp'?-10:10)*direction);savePreferences({paneSizes:state.preferences.paneSizes||{}});}});}}

let paneResizeTimer;window.addEventListener('resize',()=>{fitPanes();clearTimeout(paneResizeTimer);paneResizeTimer=setTimeout(()=>savePreferences({paneSizes:state.preferences.paneSizes}),250);});

document.addEventListener('click',safe(async event=>{const action=event.target.closest('[data-action]');if(action)await runAction(action.dataset.action);const file=event.target.closest('.file-row');if(file){if(file.dataset.directory==='true')await browse(file.dataset.path);else await openFile(file.dataset.path);}const restore=event.target.closest('[data-restore]');if(restore&&await canLeave()){const p=await api('restore',{project:state.project.id,snapshot:state.project.current,restore:restore.dataset.restore});await loadProject(p);toast('Snapshot restored as a new candidate. Original unchanged.');}const remove=event.target.closest('[data-remove-chain]');if(remove){const [id]=state.chain.splice(Number(remove.dataset.removeChain),1);if(id==='layout')state.layout=null;renderChain();}const command=event.target.closest('[data-command]');if(command){$('dialog').close();await runAction(command.dataset.command);}const recent=event.target.closest('[data-recent]');if(recent&&await canLeave()){$('dialog').close();const project=await api('project',{project:recent.dataset.recent});await browse(project.original.substring(0,project.original.lastIndexOf('/'))||'/');await loadProject(project);}if(!event.target.closest('.dropdown-menu')&&!event.target.closest('.menu-button'))document.querySelector('.dropdown-menu')?.remove();}));
on('hexRows','focusin',event=>{const cell=event.target.closest('.byte');if(cell){selectByte(Number(cell.dataset.offset));cell.select();}});
on('hexRows','input',event=>{const cell=event.target.closest('.byte');if(cell&&/^[a-fA-F0-9]{2}$/.test(cell.value)){const offset=Number(cell.dataset.offset);editByte(offset,parseInt(cell.value,16));cell.classList.toggle('changed',state.bytes[offset]!==state.original[offset]);const row=cell.closest('.hex-row');row.querySelector('.hex-ascii').textContent=Array.from(state.bytes.slice(Math.floor(offset/state.bpr)*state.bpr,Math.floor(offset/state.bpr)*state.bpr+state.bpr),b=>b>=32&&b<127?String.fromCharCode(b):'·').join('');renderInspector();}});
on('hexRows','change',event=>{const cell=event.target.closest('.byte');if(cell){const value=cell.value;if(!/^[a-fA-F0-9]{2}$/.test(value)){cell.value=state.bytes[Number(cell.dataset.offset)].toString(16).padStart(2,'0');throw Error('Each byte needs exactly two hexadecimal digits.');}editByte(Number(cell.dataset.offset),parseInt(value,16));renderHex();}});
on('hexRows','keydown',event=>{const cell=event.target.closest('.byte');if(!cell)return;let delta={ArrowLeft:-1,ArrowRight:1,ArrowUp:-state.bpr,ArrowDown:state.bpr,Enter:1}[event.key];if(delta!==undefined){event.preventDefault();cell.blur();const next=Number(cell.dataset.offset)+delta;if(next>=0&&next<state.bytes.length){if(next<state.page||next>=state.page+state.bpr*64){state.page=Math.floor(next/(state.bpr*64))*state.bpr*64;renderHex();}selectByte(next,true);}}});
on('fileFilter','input',renderFiles);on('refreshExplorer','click',()=>browse(state.folder));on('folderTitle','click',()=>pathDialog('folder'));on('parentFolder','click',()=>browse($('parentFolder').dataset.path));
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',safe(()=>setMode(b.dataset.mode))));document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>showPanel(b.dataset.panel)));
on('bytesPerRow','change',()=>{state.bpr=Number($('bytesPerRow').value);savePreferences({bytesPerRow:state.bpr});state.page=Math.floor(state.page/state.bpr)*state.bpr;renderHex();});on('previousPage','click',()=>{state.page=Math.max(0,state.page-state.bpr*64);renderHex();});on('nextPage','click',()=>{if(state.page+state.bpr*64<state.bytes.length)state.page+=state.bpr*64;renderHex();});
on('toggleInspector','click',actions.inspect);on('findButton','click',actions.find);on('closeFind','click',()=>$('findBar').hidden=true);
on('findNext','click',()=>{requireProject();const input=$('findInput').value;let needle;if($('findKind').value==='hex'){const value=input.replace(/\s/g,'');if(!/^(?:[a-fA-F0-9]{2})+$/.test(value))throw Error('Enter complete hex bytes.');needle=fromHex(value);}else needle=new TextEncoder().encode(input);if(!needle.length)return;let match=-1;for(let n=0;n<state.bytes.length;n++){const i=(state.offset+1+n)%state.bytes.length;if(i+needle.length>state.bytes.length)continue;if(needle.every((b,j)=>state.bytes[i+j]===b)){match=i;break;}}if(match<0)throw Error('No matching bytes.');setMode('hex');state.page=Math.floor(match/(state.bpr*64))*state.bpr*64;renderHex();selectByte(match,true);});
on('goOffset','click',()=>{requireProject();modal('Go to byte offset',field('offsetInput','Byte offset','0x'+address(state.offset),'text','Use a decimal number or 0x hexadecimal address.'),[{label:'Go to offset',primary:true,action:async()=>{const value=$('offsetInput').value.trim();const n=Number(value);if(!value||!Number.isInteger(n)||n<0||n>=state.bytes.length)throw Error('Offset is outside the file.');state.page=Math.floor(n/(state.bpr*64))*state.bpr*64;await setMode('hex');renderHex();$('dialog').close();selectByte(n,true);}}]);});

