on('providerSelect','change',()=>{$('modelInput').value=state.preferences.models?.[$('providerSelect').value]||'';$('modelOptions').innerHTML='';rememberModel();});on('modelInput','change',rememberModel);let modelSaveTimer;on('modelInput','input',()=>{clearTimeout(modelSaveTimer);modelSaveTimer=setTimeout(rememberModel,250);});on('profileSelect','change',()=>{saveSession();updateStatus();});
