document.addEventListener('keydown',safe(async event=>{if(!(event.metaKey||event.ctrlKey))return;const key=event.key.toLowerCase();if(event.target.closest('dialog')&&key!=='k')return;const map={o:'openFile',n:'new',s:'stage',f:'find',k:'commands'};if(map[key]){event.preventDefault();if(key==='k')commandPalette();else await runAction(map[key]);}else if(key==='enter'){event.preventDefault();await send();}else if(key==='z'&&!['TEXTAREA'].includes(event.target.tagName)&&!event.target.closest('.form-field')){event.preventDefault();await runAction(event.shiftKey?'redo':'undo');}}));
