on('panelLayout','change',()=>{const template=state.boot.templates.find(t=>t.id===$('panelLayout').value);$('panelRows').value=template.rows;$('panelColumns').value=template.columns;renderPanelLayout();});
on('panelRows','input',renderPanelLayout);on('panelColumns','input',renderPanelLayout);
on('panelUseLayout','click',()=>{const rows=Number($('panelRows').value),columns=Number($('panelColumns').value);if(!Number.isInteger(rows)||!Number.isInteger(columns)||rows<1||rows>8||columns<1||columns>8)throw Error('Choose one to eight rows and columns.');if(!state.chain.includes('layout')&&state.chain.length>=8)throw Error('A chain may contain at most eight prompts.');state.layout={template:$('panelLayout').value,rows,columns};if(!state.chain.includes('layout'))state.chain.unshift('layout');renderChain();toast('Layout prompt added. Describe your change and send when ready.');});
on('panelManagePrompts','click',()=>promptManager(false));
on('panelClearChain','click',()=>{state.chain=[];state.layout=null;renderChain();});
on('panelFeatureList','change',event=>{const input=event.target.closest('[data-prompt-feature]');if(!input)return;const id=input.dataset.promptFeature;if(input.checked){if(state.chain.length>=8){input.checked=false;throw Error('A chain may contain at most eight prompts.');}if(!state.chain.includes(id))state.chain.push(id);}else state.chain=state.chain.filter(x=>x!==id);renderChain();});
on('promptsPanel','click',event=>{const edit=event.target.closest('[data-panel-edit-prompt]');if(edit){editExtension(edit.dataset.panelEditPrompt);return;}const move=event.target.closest('[data-chain-move]');if(move){const i=Number(move.dataset.chainMove),j=i+Number(move.dataset.direction);if(j>=0&&j<state.chain.length)[state.chain[i],state.chain[j]]=[state.chain[j],state.chain[i]];renderChain();}const remove=event.target.closest('[data-chain-remove]');if(remove){const [id]=state.chain.splice(Number(remove.dataset.chainRemove),1);if(id==='layout')state.layout=null;renderChain();}});
