async function init(){state.boot=await api('bootstrap');state.preferences=state.boot.preferences||{};state.contextBytes=state.preferences.contextBytes||16384;$('contextSize').value=state.contextBytes;state.bpr=state.preferences.bytesPerRow||16;$('bytesPerRow').value=state.bpr;$('menus').innerHTML=Object.keys(menuDefs).map(name=>`<button class="menu-button" data-menu="${name}">${name}</button>`).join('');document.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>menu(b.dataset.menu,b)));$('profileSelect').innerHTML='<option value="">Choose target architecture…</option>'+state.boot.profiles.map(p=>`<option value="${p.id}">${esc(p.label)}</option>`).join('');renderProviders();initializePromptsPanel();splitters();fitPanes();try{await browse(state.preferences.folder||state.boot.workspace);}catch{await browse(state.boot.workspace);}if(state.preferences.activeProject){try{await loadProject(await api('project',{project:state.preferences.activeProject}));}catch(error){toast('Previous session could not be restored: '+error.message,true);}}showPanel(state.preferences.rightPanel||'chat');renderHex();$('extensionCount').textContent=state.boot.extensions.length;updateStatus();state.ready=true;}
safe(init)();
